missing=0
parsed=[]
for sid in unique_song_ids:
    d=apis.spotify.show_song(song_id=sid)
    rd=d.get('release_date')
    t=parse_release_date(rd)
    if t is None:
        missing+=1
        t=datetime.min
    parsed.append((t,d.get('title'),sid,d.get('release_date')))

max_t=max(x[0] for x in parsed)
max_candidates=[x for x in parsed if x[0]==max_t]
